/**
 * Admin only. MP4 or WebM, ≤ 200 MB. The server checks the real
 * container, remuxes with ffmpeg (no re-encode) dropping all metadata
 * (GPS location, device, titles), and extracts a poster frame.
 */
export const uploadVideo = async (uploadVideoBody: UploadVideoBody, options?: Parameters<typeof http>[1]): Promise<uploadVideoResponse> => {
    const formData = new FormData();
formData.append(`file`, uploadVideoBody.file);

  return http<uploadVideoResponse>(getUploadVideoUrl(),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





